export function auditLabel(action){
 const key=action?.startsWith('ruleset:')?action.split(':').slice(0,2).join(':'):action;
 return tr(actionLabels[key]||action||'');
}
export function auditPath(s){
 const q=new URLSearchParams();
 if(s.auditRole)q.set('role',s.auditRole);
 if(s.auditGroup)q.set('group',s.auditGroup);
 if(s.auditSearch)q.set('q',s.auditSearch);
 return '/admin/audit'+(q.size?'?'+q.toString():'');
}
export function auditPage(s){
 const roles={admin:'BTC',guest:'Đội',team:'Đội',student:'Sinh viên'};
 const filter=(label,name,options,value)=>`<label class="field"><span>${esc(tr(label))}</span>${select(name,[['',tr('Tất cả')],...options.map(([k,v])=>[k,tr(v)])],value||'',false)}</label>`;
 return head(tr('Nhật ký hệ thống'),tr('Thao tác của BTC, đội và hệ thống; chỉ BTC xem được. Không ghi mật khẩu hay mã nguồn.'))+
 `<div class="admin-filters">${filter('Vai trò','audit-role',[['admin','BTC'],['team','Đội / Sinh viên'],['system','Hệ thống']],s.auditRole)}${filter('Nhóm thao tác','audit-group',[['auth','Đăng nhập'],['competition','Giải đấu'],['grader','Máy chấm'],['account','Tài khoản & đội'],['results','Kết quả từ hub LAN'],['bot','Bot & GitHub']],s.auditGroup)}${field(tr('Tìm (tài khoản hoặc IP)'),'audit-search','','search',s.auditSearch||'')}</div>`+
 panel(tr('Nhật ký'),table([tr('Thời gian'),tr('Tài khoản'),'IP',tr('Thao tác'),tr('Đối tượng')],(s.audit||[]).map(a=>`<tr><td>${date(a.created_ms)}</td><td><strong>${esc(a.actor_username||tr('Hệ thống'))}</strong><div>${badge('neutral',tr(a.actor_role?(roles[a.actor_role]||a.actor_role):'Hệ thống'))}</div></td><td class="mono audit-ip">${esc(a.ip||'—')}</td><td>${esc(auditLabel(a.action))}<div class="mono muted">${esc(a.action)}</div></td><td title="${esc(a.target)}">${esc(a.target_label||short(a.target)||'—')}</td></tr>`)));
}
